#nullable enable
using Microsoft.AspNetCore.Mvc;

namespace HourBooking.Slices;

/// <summary>
/// One rejection shape for every decider, extracted when the second slice needed it — which is the
/// honest moment to extract something.
///
/// A GWT says <c>then="error: RuleName"</c>, so the rule's NAME is the machine-readable part and the
/// prose is for a human. Title carries the name; a test asserts on it, and the screen shows Detail.
///
/// Note this is NOT the same shape FluentValidation produces for a periphery rule — that middleware
/// answers with <c>{ errors: { Field: ["RuleName"] } }</c>. Two enforcement points, two shapes, and
/// the client reads both. Documented in the codegen skill because it is not obvious and it bit once.
/// </summary>
public static class Rejections
{
    public static IResult Problem(string rule, string detail) =>
        Results.Problem(new ProblemDetails
        {
            Title = rule,
            Detail = detail,
            Status = StatusCodes.Status400BadRequest,
        });
}
